mapper.select:
select bookId, bookName, bookAuthor, bookPrice, bookTypeId, bookDesc, CASE WHEN stock = 0 THEN 1 ELSE 0 END AS isBorrowed, stock, bookImg, (select bookTypeName from book_type where book_type.bookTypeId = book_info.bookTypeId) as bookTypeName from book_info
and bookName like concat('%',#{bookname},'%')
and bookAuthor like concat('%',#{bookauthor},'%')
and bookTypeId = #{booktypeid}
limit #{begin}, #{size}

